particles = []
particles2 = []
particles3 = []
particles4 = []
n = 0.1
n2 = 0.2
n3 = 0.4
n4 = 0.8

var magnetism = 20; 
var magnetism2 = 20;
var magnetism3 = 20;
var magnetism4 = 20;
var rule = 0.95; 

function setup(){
  createCanvas(windowHeight,windowHeight);

  for(i = 0; i < 10; i++){
		particles.push(createVector(width/2, height/2))
		particles2.push(createVector(width/2, height/2))
		particles3.push(createVector(random(width), random(height)))
		particles4.push(createVector(random(width), random(height)))
	}
		for(i = 0; i < 500; i++){
		x[i] = random(width);
    y[i] = height - random(height/2);
    vx[i] = 0;
    vy[i] = 0;
    ax[i] = 0;
    ay[i] = 0;

		x2[i] = random(width);
    y2[i] = random(height/2);
    vx2[i] = 0;
    vy2[i] = 0;
    ax2[i] = 0;
    ay2[i] = 0;

		x3[i] = random(width/2);
    y3[i] = random(height);
    vx3[i] = 0;
    vy3[i] = 0;
    ax3[i] = 0;
    ay3[i] = 0;

				x3[i] = random(width - width/2);
    y3[i] = random(height);
    vx3[i] = 0;
    vy3[i] = 0;
    ax3[i] = 0;
    ay3[i] = 0;
  }
}


function draw(){
colorMode(RGB)
	//background(255, 150)
  background(255, map(sin(n/10), -1, 1, random([0, 0, 0, 2]), 0))
  for(i = 0; i < 1; i++){
		p = particles[i]
		//p.x += sin(n) + map(noise(n), 0, 1, random(-0.1, -5), random(0.1, 5))
		//p.y += cos(n) + map(noise(n), 0, 1, random(-0.1, -5), random(0.1, 5))

		p.x = map(sin(n/10), -1, 1, 0, width)
		p.y = map(noise(n/10), 0, 1, 0, height)

				p2 = particles2[i]
		p2.x = map(noise(n2/10), 0, 1, 0, width)
		p2.y = map(cos(n2/10), -1, 1, 0, height)
		//stroke(255, 0, 0)
		//strokeWeight(3)
		//point(p.x, p.y)
		//point(p2.x, p2.y)

		p3 = particles3[i]
		//p3.x += sin(n) + map(noise(n), 0, 1, random(-0.1, -5), random(0.1, 5))
		//p3.y += cos(n) + map(noise(n), 0, 1, random(-0.1, -5), random(0.1, 5))

		p3.x = map(cos(n3/10), -1, 1, 0, width)
		p3.y = map(noise(n3/20), 0, 1, 0, height)

		p4 = particles4[i]
		//p4.x += sin(n4) + map(noise(n4), 0, 1, random(-0.1, -5), random(0.1, 5))
		//p4.y += cos(n4) + map(noise(n4), 0, 1, random(-0.1, -5), random(0.1, 5))

		p4.x = map(noise(n4/20), -1, 1, 0, width)
		p4.y = map(sin(n4/10), 0, 1, 0, height)
	}
    for(i = 0; i < 500; i++){					 
		strokeWeight(1)
			magnetism = map(sin(((n + n2 + n3 + n4)/4)/map(cos(n/100), -1, 1, 1, 100)), -1, 1, 0, map(noise(n/10), 0, 1, -10, 117))
			magnetism2 = map(cos(((n + n2 + n3 + n4)/4)/map(sin(n/10), -1, 1, 1, 100)), -1, 1, -1, map(noise(n/100), 0, 1, -10, 118))
			magnetism3 = map(sin(((n + n2 + n3 + n4)/4)/map(cos(n/100), -1, 1, 1, 100)), -1, 1, -2, map(noise(n/100), 0, 1, -10, 119))
			magnetism4 = map(cos(((n + n2 + n3 + n4)/4)/map(sin(n/10), -1, 1, 1, 100)), -1, 1, -3, map(noise(n/10), 0, 1, -10, 120))
			//magnetism = map(dist((p.x + p2.x + p3.x)/3, (p.y + p2.y + p3.y)/3, p.x, p.y), 0, width, 1, 60)
		distance = dist(p.x, p.y, x[i] + sin(n), y[i] + cos(n)); 
			distance2 = dist(p2.x, p2.y, x2[i] + cos(n2), y2[i] + sin(n2));
			distance3 = dist(p3.x, p3.y, x3[i] + cos(n3), y3[i] + map(noise(n3), 0, 1, -1, 1));
			distance4 = dist(p4.x, p4.y, x4[i] + cos(n4), y4[i] + map(noise(n4), 0, 1, -1, 1));
    if(distance > 3){ 
			if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) === true) {
      ax[i] = magnetism * (p.x + x[i]) / (distance * distance); 
      ay[i] = magnetism * (p.y + y[i]) / (distance * distance);
			} else {
			 ax[i] = (magnetism/2) * (p.x - x[i]) / (distance * distance); 
      ay[i] = (magnetism/2) * (p.y - y[i]) / (distance * distance);
			}
		}
			if(distance2 > 6){ 
			if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) === true) {
      ax2[i] = magnetism2 * (p2.x - x2[i]*2) / (distance2 * distance2); 
      ay2[i] = magnetism2 * (p2.y - y2[i]*2) / (distance * distance2);
			} else {
			 ax2[i] = (magnetism2/2) * (p2.x - x2[i]) / (distance2 * distance2); 
      ay2[i] = (magnetism2/2) * (p2.y - y2[i]) / (distance2 * distance2);
			}
    }

		   if(distance3 > 9){ 
			if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) === true) {
      ax3[i] = magnetism3 * (p3.x + x3[i]) / (distance3 * distance3); 
      ay3[i] = magnetism3 * (p3.y + y3[i]) / (distance3 * distance3);
			} else {
			 ax3[i] = (magnetism3/2) * (p3.x - x3[i]) / (distance3 * distance3); 
      ay3[i] = (magnetism3/2) * (p3.y - y3[i]) / (distance3 * distance3);
			}
		}	

			if(distance4 > 12){ 
			if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) === true) {
      ax4[i] = magnetism4 * (p4.x + x4[i]) / (distance4 * distance4); 
      ay4[i] = magnetism4 * (p4.y + y4[i]) / (distance4 * distance4);
			} else {
			 ax4[i] = (magnetism4/2) * (p4.x - x4[i]) / (distance4 * distance4); 
      ay4[i] = (magnetism4/2) * (p4.y - y4[i]) / (distance4 * distance4);
			}
		}	

    vx[i] += ax[i]; 
    vy[i] += ay[i]; 

    vx[i] = vx[i]*rule;
    vy[i] = vy[i]*rule;

    x[i] += vx[i]; 
    y[i] += vy[i];  

			   vx2[i] += ax2[i]; 
    vy2[i] += ay2[i]; 

    vx2[i] = vx2[i]*rule;
    vy2[i] = vy2[i]*rule;

    x2[i] += vx2[i]; 
    y2[i] += vy2[i]; 

			vx3[i] += ax3[i]; 
    vy3[i] += ay3[i]; 

    vx3[i] = vx3[i]*rule;
    vy3[i] = vy3[i]*rule;

    x3[i] += vx3[i]; 
    y3[i] += vy3[i];

			vx4[i] += ax4[i]; 
    vy4[i] += ay4[i]; 

    vx4[i] = vx4[i]*rule;
    vy4[i] = vy4[i]*rule;

    x4[i] += vx4[i]; 
    y4[i] += vy4[i];  

    var speed = dist(0,0,vx[i],vy[i]); 
			    var speed2 = dist(0,0,vx2[i],vy2[i]);
			var speed3 = dist(0,0,vx3[i],vy3[i]);
			var speed4 = dist(0,0,vx4[i],vy4[i]); 
			colorMode(HSB, 255)
					stroke(map(sin(n/100), -1, 1, 255, 0), map(cos(n/10), -1, 1, 150, 255), 255, 5)
    point(x[i],y[i]);
			point(x2[i], y2[i])
		point(x3[i], y3[i])
			 point(x4[i],y4[i]);

			stroke(map(sin(n/100), -1, 1, 0, 255), 255, map(cos(n/10), -1, 1, 150, 255), 50)
			point((x[i] + x3[i])/2, (y[i] + y3[i])/2)
			point((x[i] + x2[i])/2, (y[i] + y2[i])/2)
			point((x2[i] + x4[i])/2, (y2[i] + y4[i])/2)
			point((x[i] + x4[i])/2, (y[i] + y4[i])/2)
			point((x2[i] + x3[i])/2, (y2[i] + y3[i])/2)
				point((x3[i] + x4[i])/2, (y3[i] + y4[i])/2)

			stroke(map(sin(n/100), -1, 1, 0, 255), map((sin(n/100) + cos(n/100))/2, -1, 1, 150, 255), map(cos(n/100), -1, 1, 150, 255), 50)
			point((x[i] + x2[i] + x3[i])/3, (y[i] + y2[i] + y3[i])/3)
			point((x[i] + x2[i] + x4[i])/3, (y[i] + y2[i] + y4[i])/3)
			point((x[i] + x3[i] + x4[i])/3, (y[i] + y3[i] + y4[i])/3)
			point((x2[i] + x3[i] + x4[i])/3, (y2[i] + y3[i] + y4[i])/3)

			stroke(map(sin(n/100), -1, 1, 0, 255), map((sin(n/10) + cos(n/1000))/2, -1, 1, 150, 255), map(cos(n/1000), -1, 1, 150, 255), 50)
			point((x[i] + x2[i] + x3[i] + x4[i])/4, (y[i] + y2[i] + y3[i] + y4[i])/4)
  }
  n += random(0.1, 0.001)
	  n2 += random(0.2, 0.002)
	  n3 += random(0.4, 0.004)
	n4 += random(0.8, 0.008)
		if (!onScreen(p)) {
		p.x = random(0, width)
			p.y = random(height)
		}

		if (!onScreen(p2)) {
		p2.x = random(0, width)
			p2.y = random(height)
		}

	if (!onScreen(p3)) {
		p3.x = random(0, width)
			p3.y = random(height)
		}

	if (!onScreen(p4)) {
		p4.x = random(0, width)
			p4.y = random(height)
		}

}

function onScreen(v) {
return v.x < width && v.y < height && v.x > 0 && v.y > 0
}

